58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper) {
75	        this.clinicService = clinicService;
76	        this.ownerMapper = ownerMapper;
77	        this.petMapper = petMapper;
78	        this.visitMapper = visitMapper;
79	    }
80	
81	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
82	    @Override
83	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
84	        Collection<Owner> owners;
85	        if (lastName != null) {
86	            owners = this.clinicService.findOwnerByLastName(lastName);
87	        } else {
88	            owners = this.clinicService.findAllOwners();
89	        }
90	        if (owners.isEmpty()) {
91	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
92	        }
93	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
99	        Owner owner = this.clinicService.findOwnerById(ownerId);
100	        if (owner == null) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
104	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        if (!Postcode.isValidForCity(owner.getCity(), owner.getPostcode())) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        DailyOwnerLimitException.rejectIfAtLimit(this.clinicService.findAllOwners());
116	        boolean bulkSignupWarning = BulkSignup.isWarning(this.clinicService.findAllOwners());
117	        CityAtCapacityException.rejectIfAtCapacity(owner.getCity(), this.clinicService.findAllOwners());
118	        IdentityKey.rejectIfDuplicate(owner, this.clinicService.findAllOwners());
119	        owner.setCustomerCode(CustomerCode.assign(owner.getLastName(), owner.getCity(), this.clinicService.findAllOwners()));
120	        owner.setNamesakeCount(Namesakes.count(owner, this.clinicService.findAllOwners()));
121	        this.clinicService.saveOwner(owner);
122	        org.slf4j.LoggerFactory.getLogger("AUDIT").info("owner id={} customerCode={} registrationDate={}", owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
125	        headers.setLocation(UriComponentsBuilder.newInstance()
126	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
127	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
133	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
134	        if (currentOwner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        currentOwner.setAddress(ownerFieldsDto.getAddress());
138	        currentOwner.setCity(ownerFieldsDto.getCity());
139	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
140	        currentOwner.setLastName(ownerFieldsDto.getLastName());
141	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
142	        this.clinicService.saveOwner(currentOwner);
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Transactional
148	    @Override
149	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
150	        Owner owner = this.clinicService.findOwnerById(ownerId);
151	        if (owner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        this.clinicService.deleteOwner(owner);
155	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        HttpHeaders headers = new HttpHeaders();
166	        Pet pet = petMapper.toPet(petFieldsDto);
167	        owner.setId(ownerId);
168	        pet.setOwner(owner);
169	        pet.getType().setName(null);
170	        this.clinicService.savePet(pet);
171	        PetDto petDto = petMapper.toPetDto(pet);
172	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
173	            .buildAndExpand(pet.getId()).toUri());
174	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
180	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
181	        if (currentOwner != null) {
182	            Pet currentPet = this.clinicService.findPetById(petId);
183	            if (currentPet != null) {
184	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
185	                currentPet.setName(petFieldsDto.getName());
186	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
187	                this.clinicService.savePet(currentPet);
188	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
189	            }
190	        }
191	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
197	        HttpHeaders headers = new HttpHeaders();
198	        Visit visit = visitMapper.toVisit(visitFieldsDto);
199	        Pet pet = new Pet();
200	        pet.setId(petId);
201	        visit.setPet(pet);
202	        this.clinicService.saveVisit(visit);
203	        VisitDto visitDto = visitMapper.toVisitDto(visit);
204	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
205	            .buildAndExpand(visit.getId()).toUri());
206	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
207	    }
208	
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
213	        Owner owner = this.clinicService.findOwnerById(ownerId);
214	        if (owner != null) {
215	            Pet pet = owner.getPet(petId);
216	            if (pet != null) {
217	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
218	            }
219	        }
220	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	    }
222	}
