8	/**
9	 * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where
10	 * {@code CITY3} and {@code LAST3} are the upper-cased first three letters of the city and
11	 * last name, and {@code NNNN} is a per-city 4-digit zero-padded sequence: one more than
12	 * the owners already in that city (e.g. {@code LON-SMI-0001}).
13	 */
14	public final class CustomerCode {
15	
16	    private CustomerCode() {
17	    }
18	
19	    public static String assign(String lastName, String city, Collection<Owner> existingOwners) {
20	        long cityCount = existingOwners.stream().filter(o -> city.equalsIgnoreCase(o.getCity())).count();
21	        return String.format("%s-%s-%04d", prefix(city), prefix(lastName), cityCount + 1);
22	    }
23	
24	    private static String prefix(String value) {
25	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ENGLISH);
26	    }
27	}
