4	import java.util.Collection;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Detects an unusually high daily signup volume: true once more than 80 owners
10	 * have already been registered for today's (business-day) date.
11	 */
12	public final class BulkSignup {
13	
14	    /** Signups above this count for today trigger the warning. */
15	    private static final int THRESHOLD = 80;
16	
17	    private BulkSignup() {
18	    }
19	
20	    public static boolean isWarning(Collection<Owner> existing) {
21	        LocalDate today = BusinessDay.rollForward(LocalDate.now());
22	        long todayCount = existing.stream()
23	            .filter(owner -> today.equals(owner.getRegistrationDate()))
24	            .count();
25	        return todayCount > THRESHOLD;
26	    }
27	}
