3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Builds an owner's {@code householdId}: a stable identifier shared by every owner
10	 * in the same household, i.e. owners with the same last name and address (compared
11	 * case-insensitively with collapsed whitespace). Derived deterministically, so two
12	 * owners who share a household always resolve to the same value.
13	 */
14	public final class Household {
15	
16	    private Household() {
17	    }
18	
19	    /** The 12 upper-case hex chars of SHA-256 over the normalized {@code lastName|address}. */
20	    public static String idFor(String lastName, String address) {
21	        String key = normalize(lastName) + "|" + normalize(address);
22	        try {
23	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
24	            StringBuilder sb = new StringBuilder(12);
25	            for (int i = 0; i < 6; i++) {
26	                sb.append(String.format("%02X", digest[i]));
27	            }
28	            return sb.toString();
29	        }
30	        catch (NoSuchAlgorithmException e) {
31	            throw new IllegalStateException(e);
32	        }
33	    }
34	
35	    private static String normalize(String value) {
36	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
37	    }
38	}
